import { ElectronAPI } from '@electron-toolkit/preload'

// ---------------------------------------------------------------------------
// Shared types
// ---------------------------------------------------------------------------

/** A game entry safe to render — contains no raw file-system paths. */
export type GameEntry = {
  id: string
  name: string
  /** Base64 data URL for the cover image, if one was found on disk. */
  cover?: string
  /** CSS colour string used as the per-game accent, e.g. "#2f6bff". */
  color?: string
}

/** Returned by launchGame() and other operations that can fail. */
export type LaunchResult = {
  ok: boolean
  /** Plain-language error to show directly to the user when ok is false. */
  error?: string
}

/**
 * Returned by getStatus().
 * ok is false only when games.json exists but cannot be parsed at all.
 * Individual bad entries are skipped and described in warnings[].
 */
export type LibraryStatus = {
  ok: boolean
  games: GameEntry[]
  /** Set when the whole file cannot be parsed. */
  error?: string
  /** One string per skipped entry, describing why it was rejected. */
  warnings: string[]
}

/**
 * A game detected by scanStores() or scanFolder() that has NOT yet been
 * saved to games.json. The UI shows these for the user to confirm.
 */
export type ScanCandidate = {
  name: string
  /** Absolute exe path — present for GOG, folder-scan, and some Epic results. */
  exe?: string
  /** Store URI — present for Steam and most Epic results. */
  uri?: string
  source: 'steam' | 'epic' | 'gog' | 'folder'
}

/**
 * Returned by addGame() and editGame().
 * On success, game contains the saved entry (with its generated/existing id).
 */
export type WriteResult = {
  ok: boolean
  error?: string
  game?: GameEntry
}

/**
 * Input shape for addGame().
 * id is generated by the main process — do not send one.
 */
export type AddGameInput = {
  name: string
  exe?: string
  uri?: string
  cover?: string
  color?: string
  args?: string[]
}

/**
 * Input shape for editGame().
 * Only include the fields you want to change — the rest keep their existing values.
 * id is passed as the first argument, not inside this object.
 */
export type EditGameInput = {
  name?: string
  exe?: string
  uri?: string
  cover?: string
  color?: string
  args?: string[]
}

// ---------------------------------------------------------------------------
// Window API
// ---------------------------------------------------------------------------

declare global {
  interface Window {
    electron: ElectronAPI
    api: {
      // ── Read ──────────────────────────────────────────────────────────────
      /** Returns all valid games for display. Never throws; returns [] on error. */
      listGames(): Promise<GameEntry[]>
      /**
       * Returns the full library load result.
       * Use this to show parse errors and per-entry validation warnings.
       */
      getStatus(): Promise<LibraryStatus>

      // ── Launch + reveal ───────────────────────────────────────────────────
      /**
       * Launches a game by id.
       * The renderer sends only the id — paths and URIs come from games.json
       * inside the main process.
       */
      launchGame(id: string): Promise<LaunchResult>
      /** Opens the folder containing games.json in Windows Explorer. */
      openGamesFile(): Promise<void>
      /** Opens the folder containing the game's exe in Windows Explorer. */
      revealGame(id: string): Promise<LaunchResult>

      // ── File / folder pickers ─────────────────────────────────────────────
      /**
       * Opens a native Windows file dialog filtered to .exe files.
       * Returns the absolute path the user chose, or null if cancelled.
       * Pass this path to addGame() / editGame() — do not display it raw.
       */
      pickExe(): Promise<string | null>
      /**
       * Opens a native Windows file dialog filtered to image files.
       * Returns the absolute path the user chose, or null if cancelled.
       */
      pickCover(): Promise<string | null>
      /**
       * Opens a native Windows folder dialog.
       * Returns the absolute path the user chose, or null if cancelled.
       * Pass this path to scanFolder().
       */
      pickFolder(): Promise<string | null>

      // ── CRUD ──────────────────────────────────────────────────────────────
      /**
       * Adds a new game to games.json.
       * The main process generates a unique id; do not supply one.
       * exe and cover must be absolute paths (returned by pickExe / pickCover).
       */
      addGame(input: AddGameInput): Promise<WriteResult>
      /**
       * Updates an existing game by id.
       * Only the fields present in patch are changed; the rest are preserved.
       */
      editGame(id: string, patch: EditGameInput): Promise<WriteResult>
      /** Removes a game from games.json by id. */
      removeGame(id: string): Promise<LaunchResult>

      // ── Scanning ──────────────────────────────────────────────────────────
      /**
       * Scans Steam, Epic, and GOG for installed games.
       * Returns candidates — nothing is written until the user confirms via addGame().
       * May be slow (registry + disk reads). Call from a non-blocking context.
       */
      scanStores(): Promise<ScanCandidate[]>
      /**
       * Scans a folder (up to 3 levels deep) for .exe files.
       * folderPath must be the value returned by pickFolder().
       * Returns candidates — nothing is written until the user confirms via addGame().
       */
      scanFolder(folderPath: string): Promise<ScanCandidate[]>
    }
  }
}
